            // Map flow outputs
            link(composedFunction.getConfiguration().getOutputs(), null,
                    composedFunction.getOutputs(), ComposedFunctionOutput::getOutputName,
                    (handlerName) -> {
                        ComposedFunction handlingFunction = functions.get(handlerName);
